  function lBook(name){return state.lBooks.find(b=>b.name===name)||state.lBooks[0];}
  function lBody(kind=state.lCase){const beeCloud=state.cloud==='beecount',items=kind==='empty'?[]:state.lBooks;return `<div class="bc-subhead"><div class="bc-heading-left">${btn('back',icon('chevron-left'),'返回')}<h2>账本管理</h2></div><div class="bc-row">${btn('l-new',icon('plus'),'新建账本','bc-icon')}${btn('l-refresh',icon('refresh-cw'),'刷新账本列表','bc-icon')}</div></div>${beeCloud?menuCard([['leaf:加入共享账本','users-round','加入共享账本','通过邀请链接或邀请码加入']]):''}${items.length?`<div class="l-section">本地账本 · ${items.length}</div>`:'<div class="l-status">没有账本，创建后即可开始记录。</div>'}${items.map((b,index)=>{const selected=b.name===state.ledger;return `<section class="bc-surface j-ledger-card" data-j-ledger="${esc(b.name)}" data-current="${selected}" aria-label="${esc(b.name)}${selected?'，当前账本':''}"><div class="bc-between">${btn('j-ledger-select:'+b.name,`<span class="bc-entry-icon warm">${icon(b.shared?'users-round':'book-open')}</span><span><h3>${esc(b.name)}</h3><small>${b.currency} · ${b.count} 笔${b.shared?' · 2位成员':''}</small></span>`,selected?b.name+'，当前账本':'切换到'+b.name,'j-ledger-select',`aria-pressed="${selected}"`)}<span class="l-ledger-sync" title="未配置云端">${icon('cloud-off')}</span>${selected?`<span class="j-current-ledger">${icon('check')}当前</span>`:''}</div><div class="bc-dual j-ledger-totals"><div><label>本月支出</label><strong class="bc-num">${b.currency==='USD'?'US$':'¥'}${money(b.expense)}</strong></div><div><label>本月收入</label><strong class="bc-num">${b.currency==='USD'?'US$':'¥'}${money(b.income)}</strong></div></div><p class="l-ledger-balance">累计结余 ${b.currency==='USD'?'US$':'¥'}${money(b.balance)}</p><div class="j-ledger-actions">${btn('ledger-budget:'+b.name,`${icon('chart-pie')}预算管理`,b.name+'预算管理','bc-secondary')}${b.shared&&beeCloud?btn('j-ledger-direct:'+b.name,`${icon('users-round')}成员管理`,'成员管理','bc-secondary'):state.fRole!=='编辑者'?btn('j-ledger-direct:'+b.name,`${icon('settings-2')}编辑账本`,'编辑账本','bc-secondary'):''}${btn('j-ledger-menu:'+b.name,icon('ellipsis'),b.name+'更多操作','j-ledger-more','aria-haspopup="dialog"')}</div></section>`;}).join('')}${['remote','loading','error'].includes(kind)?`<div class="l-section">云端账本${kind==='remote'?' · 1'+btn('l-restore-all','恢复全部','恢复全部云端账本','bc-link'):''}</div>${kind==='loading'?'<div class="l-status" role="status">正在加载云端账本…本地账本可以正常使用。</div>':kind==='error'?`<div class="l-status" data-error="true">云端列表获取失败，本地数据仍保留。${btn('l-refresh','重试','重试加载账本','bc-secondary')}</div>`:`<section class="bc-surface j-ledger-card" data-j-ledger="云端旅行"><div class="bc-between"><h3>云端旅行</h3>${icon('cloud-download')}</div><p class="bc-small">USD · 12 笔 · 2026-10-23 12:30</p><p class="l-ledger-balance">下载云账本</p><div class="j-ledger-actions">${btn('l-remote-download','下载','下载云端旅行','bc-secondary')}${btn('l-remote-menu',icon('ellipsis'),'云端旅行更多操作','j-ledger-more')}</div></section>`}`:''}${btn('l-new',`${icon('plus')}新建账本`,'新建账本','bc-primary')}`;}
  ledgers=function(){return lBody();};
  function lEditor(name){const b=state.lBooks.find(x=>x.name===name);state.lEditing=b?.name||'';state.lName=b?.name||'';state.lCurrency=b?.currency||'CNY';state.lDay=b?.day||1;rSpecs['ledger-edit'].title=b?'编辑账本':'新建账本';rDismiss();rOpenModal('ledger-edit');}
  rSpecs['ledger-edit']={title:'编辑账本',host:'ledgers',kind:'dialog'};
  rLedgerForm=function(){return `<label class="l-editor-field">名称<input data-l-ledger-name aria-label="账本名称" value="${esc(state.lName)}" placeholder="账本名称"></label>${menuRow('l-currency','coins','主币种',state.lCurrency)}${menuRow('l-period','calendar-days','每月起始日',state.lDay===1?'1日（自然月）':'每月'+state.lDay+'日')}<div class="bc-inline-actions">${btn('r-close','取消','取消','bc-secondary')}${btn('l-edit-save',state.lEditing?'保存':'创建','保存账本草稿','bc-primary',state.lName.trim()?'':'disabled')}</div>`;};
  jLedgerMenu=function(){const b=lBook(state.jMenuLedger),owner=state.fRole!=='编辑者',beeCloud=state.cloud==='beecount';return `<div class="j-ledger-context"><span class="bc-entry-icon warm">${icon(b.shared?'users-round':'book-open')}</span><div><h3>${esc(b.name)}</h3><small>${b.currency} · ${b.count}笔${b.shared?' · '+(owner?'所有者':'编辑者'):''}</small></div></div><p class="l-ledger-meta">ID: ${state.lBooks.indexOf(b)+1}</p><div class="j-ledger-menu">${owner?menuRow('j-ledger-action:edit','pencil','编辑账本'):''}${menuRow('j-ledger-action:budget','chart-pie','预算管理')}${beeCloud?menuRow('j-ledger-action:members','users-round','成员管理')+(b.shared?menuRow('j-ledger-action:stats','chart-no-axes-combined','成员统计'):''):''}${owner?menuRow('j-ledger-action:clear','list-x','清空账本'):''}${menuRow('j-ledger-action:local','folder-minus','仅删除本地账本')}${owner?menuRow('j-ledger-action:delete','trash-2','删除账本'):''}</div>`;};
  const lPreviousAction=jLedgerAction;
  jLedgerAction=function(action,name=state.jMenuLedger){if(action==='edit'){lEditor(name);return;}if(['clear','local','delete'].includes(action)){state.lPending=action;state.jMenuLedger=name;rOpenModal('ledger-confirm');return;}lPreviousAction(action,name);};
  function lDayGrid(){return `<p class="bc-small">统计与预算按该日作为每月周期起点（1–28）。</p><div class="l-day-grid">${Array.from({length:28},(_,i)=>btn('l-day:'+(i+1),String(i+1),'每月'+(i+1)+'日','',`aria-pressed="${state.lDay===i+1}"`)).join('')}</div>`;}
  function lCurrencies(){const q=state.lCurrencyQuery.toLowerCase().trim();return `<label class="p-search-box"><input data-l-currency-query aria-label="搜索账本币种" placeholder="搜索币种" value="${esc(state.lCurrencyQuery)}"></label><div class="v-currency-list">${wCurrencies.filter(c=>!q||[c.code,wCurrencyName(c),c.symbol].join(' ').toLowerCase().includes(q)).map(c=>btn('l-currency-select:'+c.code,`${esc(c.symbol)}<span>${esc(wCurrencyName(c))} (${c.code})</span>${state.lCurrency===c.code?icon('check'):''}`,'选择'+c.code,'v-currency-row')).join('')}</div>`;}
  function lCommit(){if(!state.lName.trim())return notice('请输入账本名称');const old=state.lBooks.find(b=>b.name===state.lEditing);if(old)Object.assign(old,{name:state.lName.trim(),currency:state.lCurrency,day:state.lDay});else state.lBooks.push({name:state.lName.trim(),currency:state.lCurrency,day:state.lDay,count:0,balance:0,expense:0,income:0});if(state.ledger===state.lEditing)state.ledger=state.lName.trim();rDismiss();state.page='ledgers';state.lCase='normal';render();notice('账本设置已保存');}
  Object.assign(rSpecs,{'ledger-period':{title:'每月起始日',host:'ledgers',kind:'sheet'},'ledger-currencies':{title:'选择货币',host:'ledgers',kind:'sheet'},'ledger-confirm':{title:'确认账本操作',host:'ledgers',kind:'dialog'},'ledger-currency-confirm':{title:'主币种',host:'ledgers',kind:'dialog'},'ledger-conflict':{title:'同步冲突',host:'ledgers',kind:'dialog'},'ledger-remote-actions':{title:'账本操作',host:'ledgers',kind:'dialog'},'ledger-create':{title:'新建账本',host:'ledgers',kind:'dialog'}});
  const lPreviousModal=rModalBody;
  rModalBody=function(key){if(key==='ledger-create')return rLedgerForm();if(key==='ledger-remote-actions')return `<h3>云端旅行</h3><p class="bc-small">USD · 12笔 · 2026-10-23 12:30</p>${menuRow('l-remote-download','cloud-download','下载')}${menuRow('l-remote-delete','trash-2','删除云端账本')}`;if(key==='ledger-period')return lDayGrid();if(key==='ledger-currencies')return lCurrencies();if(key==='ledger-currency-confirm')return `<p>修改本位币将按当前汇率重算全部历史交易的折算值。</p><p class="bc-small">${lBook(state.lEditing)?.count||0} 笔账单将重新折算并同步。</p>${rModalActions('r-close','取消','l-currency-confirm','确定')}`;if(key==='ledger-confirm'){const labels={clear:'清空账本',local:'仅删除本地账本',delete:'删除账本',download:'下载账本',restore:'恢复全部云端账本'};return `<p>${labels[state.lPending]}：${esc(state.jMenuLedger)}</p><p class="bc-small">${state.lPending==='local'?'只移除本地副本，云端数据保留。':state.lPending==='clear'?'保留账本，只清空其中账单及不再引用的附件。':'请核对所选账本，取消不会改动数据。'}</p>${rModalActions('r-close','取消','l-confirm','确定')}`;}if(key==='ledger-conflict')return `<p>本地与云端有差异，请先核对再选择。</p><div class="l-conflict-info">本地：48笔<br>本地指纹：2c5b01a7</div><div class="l-conflict-info">云端：46笔<br>云端更新：2026-10-23 12:30<br>云端指纹：9d240b01</div><div class="bc-inline-actions">${btn('r-close','取消','取消','bc-secondary')}${btn('l-conflict-download','下载到本地','下载到本地','bc-secondary')}${btn('l-conflict-upload','上传到云端','上传到云端','bc-primary')}</div>`;return lPreviousModal(key);};
  root.addEventListener('input',e=>{if(e.target.matches('[data-l-ledger-name]')){state.lName=e.target.value;const save=phone.querySelector('[data-action="l-edit-save"]');if(save)save.disabled=!state.lName.trim();}if(e.target.matches('[data-l-currency-query]')){state.lCurrencyQuery=e.target.value;const pos=e.target.selectionStart;rBuildModal();const input=phone.querySelector('[data-l-currency-query]');input.focus({preventScroll:true});input.setSelectionRange(pos,pos);}});
  root.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(!action.startsWith('l-')&&!action.startsWith('j-ledger-direct:')&&action!=='leaf:新建账本')return;e.preventDefault();e.stopImmediatePropagation();if(action==='l-new'||action==='leaf:新建账本')lEditor('');else if(action==='l-refresh'){notice('已重新检查账本列表');}else if(action.startsWith('j-ledger-direct:')){const name=action.slice('j-ledger-direct:'.length),b=lBook(name);if(b.shared&&state.cloud==='beecount')jLedgerAction('members',name);else lEditor(name);}else if(action==='l-currency'){state.lCurrencyQuery='';rOpenModal('ledger-currencies');}else if(action==='l-period')rOpenModal('ledger-period');else if(action.startsWith('l-day:')){state.lDay=Number(action.split(':')[1]);rClose();}else if(action.startsWith('l-currency-select:')){state.lCurrency=action.split(':')[1];rClose();}else if(action==='l-edit-save'){if(state.lEditing&&state.lCurrency!==lBook(state.lEditing).currency)rOpenModal('ledger-currency-confirm');else lCommit();}else if(action==='l-currency-confirm')lCommit();else if(action==='l-remote-menu'){rOpenModal('ledger-remote-actions');}else if(['l-remote-download','l-remote-delete','l-restore-all'].includes(action)){state.lPending=action==='l-restore-all'?'restore':action==='l-remote-delete'?'delete':'download';state.jMenuLedger='云端旅行';rOpenModal('ledger-confirm');}else if(action==='l-confirm'){rDismiss();render();notice('操作已确认 · 设计示例');}else if(action.startsWith('l-conflict-')){rDismiss();render();notice('已选择同步方向 · 设计示例');}},true);
  const lScenes=[['ledgers-empty','账本 · 无账本与创建','empty'],['ledgers-remote','账本 · 云端独立账本','remote'],['ledgers-loading','账本 · 云端加载本地可用','loading'],['ledgers-error','账本 · 云端错误与重试','error'],['ledgers-editor','账本 · 编辑者操作范围','editor']];
  const lPreviewGroup=picker.querySelector('optgroup[label="账本与共享"]')||picker;
  for(const [key,title,kind] of lScenes){fDefine(key,title,'账本与共享','main/ledgers_page_new.dart',()=>lBody(kind==='editor'?'normal':kind));lPreviewGroup.appendChild(new Option(title,'flow-'+key));}
  for(const [key,title,body] of [['ledger-create','账本 · 新建美元与28日起始日',rLedgerForm],['ledger-remote-actions','账本 · 云端操作菜单',()=>rModalBody('ledger-remote-actions')],['ledger-period','账本 · 月起始日选择',lDayGrid],['ledger-currencies','账本 · 全部币种选择',lCurrencies],['ledger-conflict','账本 · 冲突处理',()=>rModalBody('ledger-conflict')]]){fDefine(key,title,'账本与共享','main/ledgers_page_new.dart',body);lPreviewGroup.appendChild(new Option(title,'flow-'+key));}
  const lPreviousPrepare=rPrepareRoute;
  rPrepareRoute=function(){if(state.page==='flow-ledger-create'){state.lEditing='';state.lName='';state.lCurrency='USD';state.lDay=28;}if(state.page==='flow-ledgers-editor'){state.fRole='编辑者';state.cloud='beecount';}else if(state.page.startsWith('flow-ledgers-')){state.fRole='所有者';state.cloud=state.page==='flow-ledgers-remote'?'beecount':'local';}lPreviousPrepare();};
